#polymer = "dabAcCaCBAcCcaDA"
polymer = ""


last_index = 0
while True:
    completed = False
    if last_index > 0:
        last_index -= 1
    for i in range(last_index, len(polymer) - 1):
        if polymer[i].isupper() != polymer[i + 1].isupper():
            if polymer[i].lower() == polymer[i + 1].lower():
                polymer = polymer[:i] + polymer[i + 2:]
                last_index = i
                break
        if i == len(polymer) - 2:
            completed = True
    if completed:
        break
print(polymer)
print(len(polymer))
